def pre(n):
    if n < 0:
        return False
    if n > 250:
        return False
    return True

def post(n, result):
    expected = True
    if n < 2:
        expected = False
    else:
        d = 2
        while d * d <= n:
            if n % d == 0:
                expected = False
                break
            d = d + 1
    return result == expected
